test('WhatsApp pricing rechecks positive readiness, exact native identity and access after provider and final account awaits', async () => {
  const path = '/whatsapp/pricing-analytics';
  for (const field of ['inactive', 'unknown-activity', 'reconnect', 'duplicate']) {
    const { accounts, state, calls, request } = setup(), account = accounts.find(row => row.platform === 'whatsapp'); state.override.set(path, pricingReply());
    if (field === 'inactive') account.isActive = false; if (field === 'unknown-activity') delete account.isActive; if (field === 'reconnect') account.needsReconnection = true; if (field === 'duplicate') accounts.push({ ...account });
    assert.equal((await request('whatsapp-a/whatsapp-pricing' + dateQuery)).status, 409, field); assert.equal(calls.some(row => row.path === path), false);
  }
  for (const stage of ['provider', 'final-account']) for (const field of ['native-id', 'username', 'inactive', 'reconnect', 'platform', 'removed', 'duplicate', 'access']) {
    const { accounts, state, request } = setup(), account = accounts.find(row => row.platform === 'whatsapp'); state.override.set(path, pricingReply()); let accountReads = 0;
    state.onCall = next => { if (next === '/accounts') accountReads++; if (stage === 'provider' ? next !== path : next !== '/accounts' || accountReads !== 2) return;
      if (field === 'native-id') account.platformUserId = 'changed-native-phone'; if (field === 'username') account.username = 'changed-phone-label'; if (field === 'inactive') account.isActive = false; if (field === 'reconnect') account.needsReconnection = true; if (field === 'platform') account.platform = 'facebook'; if (field === 'removed') accounts.splice(accounts.indexOf(account), 1); if (field === 'duplicate') accounts.push({ ...account }); if (field === 'access') state.accessError = new IntegrationError(403, 'PROJECT_ACCESS_CHANGED', 'Project access changed.'); };
    const result = await request('whatsapp-a/whatsapp-pricing' + dateQuery); assert.ok([403, 409].includes(result.status), stage + ':' + field + JSON.stringify(result)); assert.equal(result.data.report, undefined);
  }
  const { accounts, state, request } = setup(); state.override.set(path, pricingReply()); state.onCall = next => { if (next === path) accounts.find(row => row.platform === 'whatsapp').followersCount = 12; }; assert.equal((await request('whatsapp-a/whatsapp-pricing' + dateQuery)).status, 200, 'Unrelated volatile account metadata does not invalidate this read.');
});

